import{_ as a,o as e,c as s,a4 as i}from"./chunks/framework.BBs01uty.js";const g=JSON.parse('{"title":"IntelliJ IDEA 使用指南（Java 后端实战版）","description":"","frontmatter":{},"headers":[],"relativePath":"java-practice/08-intellij-idea.md","filePath":"java-practice/08-intellij-idea.md"}'),o={name:"java-practice/08-intellij-idea.md"};function l(n,t,d,r,h,c){return e(),s("div",null,[...t[0]||(t[0]=[i(`<h1 id="intellij-idea-使用指南-java-后端实战版" tabindex="-1">IntelliJ IDEA 使用指南（Java 后端实战版） <a class="header-anchor" href="#intellij-idea-使用指南-java-后端实战版" aria-label="Permalink to &quot;IntelliJ IDEA 使用指南（Java 后端实战版）&quot;">​</a></h1><blockquote><p><strong>目标</strong>：用最短时间学会 IDEA 里日常写 Java 后端必需的操作。按&quot;学习计划用得上&quot;来组织，不铺开所有功能。</p><p><strong>适合</strong>：从 VS Code 转过来了的人。IDEA 和 VS Code 的对应关系会标出来。</p></blockquote><h2 id="一、idea-vs-vs-code-先建立对应关系" tabindex="-1">一、IDEA vs VS Code（先建立对应关系） <a class="header-anchor" href="#一、idea-vs-vs-code-先建立对应关系" aria-label="Permalink to &quot;一、IDEA vs VS Code（先建立对应关系）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>你熟悉的 VS Code</th><th>IDEA 对应</th></tr></thead><tbody><tr><td>侧边栏资源管理器</td><td>左侧 Project 面板（Cmd+1）</td></tr><tr><td>Cmd+P 打开文件</td><td><strong>Cmd+Shift+O</strong>（找文件）/ <strong>Cmd+O</strong>（找类）</td></tr><tr><td>Cmd+F 当前文件搜索</td><td>相同</td></tr><tr><td>Cmd+Shift+F 全局搜索</td><td><strong>Cmd+Shift+F</strong>（跨文件搜索代码）/ <strong>Double Shift</strong>（搜索一切）</td></tr><tr><td>点击函数名跳定义</td><td><strong>Cmd+点击</strong> 或 <strong>Cmd+B</strong></td></tr><tr><td>调试断点</td><td>相同（行号左侧点红点）</td></tr><tr><td>终端</td><td>底部 Terminal 标签页</td></tr><tr><td>插件市场</td><td>Settings → Plugins</td></tr></tbody></table><blockquote><p>最大差异：IDEA 对 Java 的理解更深。<strong>Cmd+点击能直接跳到 Spring Bean 的声明、Mapper 的 XML、甚至 <code>@Autowired</code> 注入的实现类</strong>，这是 VS Code 做不到的，也是你读 mall 源码的最强武器。</p></blockquote><h2 id="二、打开和配置项目" tabindex="-1">二、打开和配置项目 <a class="header-anchor" href="#二、打开和配置项目" aria-label="Permalink to &quot;二、打开和配置项目&quot;">​</a></h2><h3 id="打开-maven-项目" tabindex="-1">打开 Maven 项目 <a class="header-anchor" href="#打开-maven-项目" aria-label="Permalink to &quot;打开 Maven 项目&quot;">​</a></h3><ol><li><code>File → Open</code> 选 mall 根目录</li><li>IDEA 识别到 <code>pom.xml</code> 会自动开始 <strong>导入 Maven 依赖</strong>（右下角转圈）</li><li>首次导入要等依赖下载完（走了阿里云镜像会快），<strong>没下完就运行会报&quot;找不到类&quot;</strong></li></ol><blockquote><p>手动刷新依赖：右侧 <strong>Maven 工具窗口</strong>（侧边栏 M 图标）→ 点刷新按钮（↻）。</p></blockquote><h3 id="配置-jdk-project-structure" tabindex="-1">配置 JDK（Project Structure） <a class="header-anchor" href="#配置-jdk-project-structure" aria-label="Permalink to &quot;配置 JDK（Project Structure）&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>File → Project Structure…（Cmd + ;）→ Project → SDK</span></span></code></pre></div><ul><li>SDK 下拉 → <code>Add JDK…</code> → 选 JDK 目录（如 <code>~/Library/Java/JavaVirtualMachines/zulu17.../Contents/Home</code>）</li><li><strong>Language level</strong> 要和 SDK 匹配（JDK 17 就选 17）</li><li>一个 IDEA 窗口只能同时跑一个 Project 的 SDK，但<strong>机器上装多个 JDK 可以随时切换</strong>（mall 用 17，如果你以后写 JDK 8 的老项目切回去就行）</li></ul><blockquote><p>报&quot;源发行版 xx 需要目标发行版 xx&quot; = 项目的 Language level 和编译 JDK 不一致，去这里改。</p></blockquote><h2 id="三、运行和调试-核心技能" tabindex="-1">三、运行和调试（核心技能） <a class="header-anchor" href="#三、运行和调试-核心技能" aria-label="Permalink to &quot;三、运行和调试（核心技能）&quot;">​</a></h2><h3 id="运行-spring-boot-应用" tabindex="-1">运行 Spring Boot 应用 <a class="header-anchor" href="#运行-spring-boot-应用" aria-label="Permalink to &quot;运行 Spring Boot 应用&quot;">​</a></h3><ul><li>打开主类（<code>MallAdminApplication</code>），点 <code>main</code> 方法左边的<strong>绿色三角 ▶</strong> → <code>Run</code></li><li>或者点虫子图标（Debug）——<strong>平时都用 Debug 跑</strong>，这样能随时打断点</li></ul><h3 id="打断点调试-读代码必备" tabindex="-1">打断点调试（读代码必备） <a class="header-anchor" href="#打断点调试-读代码必备" aria-label="Permalink to &quot;打断点调试（读代码必备）&quot;">​</a></h3><ol><li>在想停的行号左侧<strong>点红点</strong></li><li>用 <strong>Debug</strong> 启动（不是 Run）</li><li>请求进来自动停在断点，看底部 <strong>Debugger 面板</strong>：</li></ol><table tabindex="0"><thead><tr><th>操作</th><th>快捷键</th><th>作用</th></tr></thead><tbody><tr><td>Step Over</td><td><strong>F8</strong></td><td>执行当前行，不进入方法（快速过）</td></tr><tr><td>Step Into</td><td><strong>F7</strong></td><td>进入方法内部（跟链路）</td></tr><tr><td>Step Out</td><td><strong>Shift+F8</strong></td><td>跳出当前方法</td></tr><tr><td>Resume</td><td><strong>Cmd+Option+R</strong></td><td>跑到下一个断点</td></tr><tr><td>停下</td><td>点红色方块 ■</td><td>终止程序</td></tr></tbody></table><ol start="4"><li>右侧 <strong>Variables</strong> 窗口看当前所有变量值；鼠标悬停变量也能看</li></ol><blockquote><p><strong>读 mall 的正确姿势</strong>：在 <code>UmsAdminServiceImpl.login()</code> 打断点 → 用 Swagger 调登录 → F8 单步 → 亲眼看到数据怎么流。比看代码猜快十倍。</p></blockquote><h3 id="条件断点-进阶" tabindex="-1">条件断点（进阶） <a class="header-anchor" href="#条件断点-进阶" aria-label="Permalink to &quot;条件断点（进阶）&quot;">​</a></h3><p>右键红点 → 填条件（如 <code>username.equals(&quot;admin&quot;)</code>），只有满足条件才停。调试循环/列表时超好用。</p><h2 id="四、读代码的五件武器" tabindex="-1">四、读代码的五件武器 <a class="header-anchor" href="#四、读代码的五件武器" aria-label="Permalink to &quot;四、读代码的五件武器&quot;">​</a></h2><p><strong>1. Cmd+点击 / Cmd+B：跳转到定义</strong>（VS Code 也有，但 IDEA 更智能）</p><ul><li>点 <code>adminService.login(...)</code> → 直接跳到 <code>UmsAdminServiceImpl.login()</code> 实现</li><li>点 <code>PmsProductMapper</code> 的方法 → 能跳到 <code>PmsProductMapper.xml</code> 的 SQL</li></ul><p><strong>2. Cmd+Alt+B：跳转实现类</strong></p><ul><li>光标放在接口方法上 → 列出所有实现，选一个跳转（如 <code>PmsProductService</code> → 找实现类）</li></ul><p><strong>3. Double Shift：搜索一切</strong></p><ul><li>输类名/文件名/方法名/设置项，全能搜。比在文件树里翻快得多</li></ul><p><strong>4. Cmd+F / Cmd+Shift+F：当前文件 / 全局搜索</strong></p><ul><li>全局搜关键词（如 <code>secure.ignored.urls</code>、<code>@Transactional</code>），快速定位代码</li></ul><p><strong>5. Cmd+P：查看方法参数</strong></p><ul><li>在方法调用处按 Cmd+P，显示参数列表，不用跳进方法也能知道传什么</li></ul><p><strong>6. 红/绿色高亮 + Alt+Enter：错误提示</strong></p><ul><li>代码报错会红色波浪线，<strong>光标放上去按 Alt+Enter</strong>，IDEA 会给出修复建议/导入缺失类</li></ul><blockquote><p>建议记熟前 4 个，读 mall 就够用了。</p></blockquote><h2 id="五、maven-工具窗口" tabindex="-1">五、Maven 工具窗口 <a class="header-anchor" href="#五、maven-工具窗口" aria-label="Permalink to &quot;五、Maven 工具窗口&quot;">​</a></h2><p>右侧边栏点 <strong>M</strong> 图标（Maven 窗口）：</p><ul><li><strong>Lifecycle</strong>：<code>clean</code>（清编译产物）、<code>package</code>（打包 jar）、<code>install</code>（装进本地仓库）</li><li><strong>Plugins</strong>：spring-boot 相关插件</li><li>展开每个模块（mall-admin、mall-common…）都能单独操作</li><li>顶部 ↻ 刷新按钮：pom.xml 改了依赖后点它重新加载</li></ul><blockquote><p>日常开发：依赖有问题先点刷新；打包用 <code>package</code>（输出在 <code>target/</code> 目录）。</p></blockquote><h2 id="六、数据库连接-看库数据" tabindex="-1">六、数据库连接（看库数据） <a class="header-anchor" href="#六、数据库连接-看库数据" aria-label="Permalink to &quot;六、数据库连接（看库数据）&quot;">​</a></h2><blockquote><p>注意：IDEA <strong>社区版没有 Database 面板</strong>（那是旗舰版 Ultimate 的功能，你装的是社区版）。看库数据有三个方案：</p></blockquote><p><strong>方式一：命令行（最简，零安装）</strong></p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -it</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mysql8</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mysql</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -uroot</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -proot</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mall</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">show</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tables</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;                              </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 看所有表</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">select</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> * from ums_admin;                  </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 查 admin 表数据</span></span></code></pre></div><p><strong>方式二：DBeaver（免费 GUI，推荐日常用）</strong></p><blockquote><p>安装注意：<code>brew install --cask dbeaver-community</code> 在国内网络会卡死（安装包托管在 GitHub releases）。实测可用的安装方式：</p></blockquote><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 1. 从官方 GitHub 加速代理下载（ghfast.top 等，速度可达 10MB/s+）</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 先查最新版本号，以 26.1.5 为例（Apple Silicon 用 aarch64 包）：</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -L</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/Downloads/dbeaver-ce.dmg</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  &quot;https://ghfast.top/https://github.com/dbeaver/dbeaver/releases/download/26.1.5/dbeaver-ce-26.1.5-macos-aarch64.dmg&quot;</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 2. 挂载安装</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">hdiutil</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> attach</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/Downloads/dbeaver-ce.dmg</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -nobrowse</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cp</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -R</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;/Volumes/DBeaver Community/DBeaver.app&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /Applications/</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">hdiutil</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> detach</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;/Volumes/DBeaver Community&quot;</span></span></code></pre></div><p>安装后用 <code>New Connection → MySQL</code> 建连接（Host <code>localhost</code> / Port <code>3306</code> / Database <code>mall</code> / User <code>root</code> / Password <code>root</code>）。能看表结构、跑 SQL、双击看数据。首次连接需下载 MySQL 驱动（从 Maven 仓库），失败的话在 <code>Preferences → Drivers → MySQL → Edit → Maven</code> 里加阿里云镜像。</p><p><strong>方式三：VS Code Database 插件</strong>（你熟 VS Code 的话）：装 <code>Database Client</code> 之类的插件，同样填上面的连接信息。</p><blockquote><p>配合调试：在代码里看到某张表，切到数据库工具查数据，理解代码在操作什么。</p></blockquote><h2 id="七、终端和-git" tabindex="-1">七、终端和 Git <a class="header-anchor" href="#七、终端和-git" aria-label="Permalink to &quot;七、终端和 Git&quot;">​</a></h2><ul><li><strong>底部 Terminal 标签页</strong>：内置终端，直接 <code>docker ps</code>、<code>mvn</code> 都能跑</li><li><strong>Git 集成</strong>：右侧 Git 面板看 diff；文件右键 → Git → Commit；IDEA 会标出改动的文件（蓝色=改过，绿色=新增）</li><li>提交前在底部 <code>Git</code> 工具窗口检查 diff，别把无关文件提交了</li></ul><h2 id="八、常见问题" tabindex="-1">八、常见问题 <a class="header-anchor" href="#八、常见问题" aria-label="Permalink to &quot;八、常见问题&quot;">​</a></h2><p><strong>Q：运行报&quot;找不到主类&quot;？</strong> A：Project Structure → Modules 确认当前模块被标记为 sources；或 Maven 窗口对模块执行 <code>clean</code> 后再 <code>compile</code>。</p><p><strong>Q：代码全是红色报错但 Maven 依赖明明有？</strong> A：Maven 窗口点刷新 ↻ 重新导入；还不行就 <code>File → Invalidate Caches...</code> 清缓存重启。</p><p><strong>Q：Maven 下载依赖很慢/失败？</strong> A：确认 <code>~/.m2/settings.xml</code> 配了阿里云镜像（本项目环境已配好）；失败多是网络问题，再点一次刷新。</p><p><strong>Q：字体太小/主题不习惯？</strong> A：<code>Settings（Cmd+,）→ Appearance &amp; Behavior</code> 调主题字号；<code>Editor → Font</code> 调代码字号。</p><h2 id="九、学习计划中怎么用它" tabindex="-1">九、学习计划中怎么用它 <a class="header-anchor" href="#九、学习计划中怎么用它" aria-label="Permalink to &quot;九、学习计划中怎么用它&quot;">​</a></h2><table tabindex="0"><thead><tr><th>阶段</th><th>IDEA 用法</th></tr></thead><tbody><tr><td>阶段 1</td><td>Debug + F8 走登录链路；Double Shift 找类</td></tr><tr><td>阶段 2</td><td>Cmd+点击 跳 Controller→Service→Mapper→XML</td></tr><tr><td>阶段 3</td><td>打断点看 Example 条件拼接；Database 面板看 SQL 效果</td></tr><tr><td>阶段 4</td><td>配合 redis-cli 验证缓存（Terminal 标签页）</td></tr><tr><td>阶段 5</td><td>Cmd+Alt+B 找实现类，理解代理结构</td></tr><tr><td>阶段 6</td><td>自己写代码：Alt+Enter 导包、Cmd+P 看参数</td></tr></tbody></table><blockquote><p>最快的学习方式：<strong>一边 Debug 一边读</strong>。把读 mall 当&quot;开着导航开车&quot;，断点就是路标。</p></blockquote>`,61)])])}const u=a(o,[["render",l]]);export{g as __pageData,u as default};
